css:
/* Optimize the Chain v2 · namespaced to .chainsim-container */
.chainsim-container {
    --cs-bg: #f6f4ef;
    --cs-surface: #ffffff;
    --cs-surface-2: #f0ece3;
    --cs-ink: #1d1b18;
    --cs-ink-2: #4a463f;
    --cs-line: #d9d2c3;
    --cs-accent: #0b6e4f;
    --cs-accent-ink: #ffffff;
    --cs-accent-soft: #e3f1ea;
    --cs-warn: #8a5a00;
    --cs-warn-soft: #fbf0d9;
    --cs-bad: #a1261b;
    --cs-bad-soft: #fbe6e3;
    --cs-good: #1f6b2e;
    --cs-good-soft: #e5f2e7;
    --cs-focus: #1a56db;
    --cs-r: 10px;
    --cs-s1: 4px; --cs-s2: 8px; --cs-s3: 12px; --cs-s4: 16px; --cs-s5: 24px; --cs-s6: 32px;
    color-scheme: light;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    font-size: 16px;
    line-height: 1.5;
    color: var(--cs-ink);
    background: var(--cs-bg);
    max-width: 1180px;
    margin: 0 auto;
    padding: var(--cs-s5);
    border-radius: 14px;
}
.chainsim-container *, .chainsim-container *::before, .chainsim-container *::after { box-sizing: border-box; }
.chainsim-container .cs-visually-hidden { position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

.chainsim-container .cs-header { background: var(--cs-surface); color: var(--cs-ink); border: 1px solid var(--cs-line); border-left: 6px solid var(--cs-accent); border-radius: var(--cs-r); padding: var(--cs-s3) var(--cs-s5); margin-bottom: var(--cs-s3); }
.chainsim-container .cs-tag { margin: 0; font-size: 0.8rem; font-weight: 600; letter-spacing: 0.02em; color: var(--cs-accent); background: var(--cs-surface); }
.chainsim-container .cs-title { margin: 2px 0 var(--cs-s1); font-size: 1.6rem; line-height: 1.2; font-weight: 750; color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-role { margin: 0; max-width: 90ch; font-size: 0.95rem; color: var(--cs-ink-2); background: var(--cs-surface); }

.chainsim-container .cs-status { background: var(--cs-bg); padding: var(--cs-s1) 0 var(--cs-s3); }
.chainsim-container .cs-roundbar { display: flex; flex-wrap: wrap; gap: var(--cs-s2) var(--cs-s4); align-items: center; margin-bottom: var(--cs-s2); }
.chainsim-container .cs-roundchip { margin: 0; padding: var(--cs-s1) var(--cs-s3); border-radius: 999px; background: var(--cs-accent); color: var(--cs-accent-ink); font-weight: 650; }
.chainsim-container .cs-roundname { font-weight: 500; margin-left: var(--cs-s1); color: var(--cs-accent-ink); background: var(--cs-accent); }
.chainsim-container .cs-clock { margin: 0; color: var(--cs-ink-2); background: var(--cs-bg); font-size: 0.95rem; }
.chainsim-container .cs-clause { margin: 0; font-size: 0.9rem; font-weight: 600; padding: var(--cs-s1) var(--cs-s3); border-radius: 999px; color: var(--cs-warn); background: var(--cs-warn-soft); }
.chainsim-container .cs-clause.cs-is-bad { color: var(--cs-bad); background: var(--cs-bad-soft); }
.chainsim-container .cs-clause.cs-is-good { color: var(--cs-good); background: var(--cs-good-soft); }

.chainsim-container .cs-kpis { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: var(--cs-s2); }
.chainsim-container .cs-kpi { background: var(--cs-surface); border: 1px solid var(--cs-line); border-radius: var(--cs-r); padding: var(--cs-s2) var(--cs-s3); display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.chainsim-container .cs-kpi-label { font-size: 0.8rem; font-weight: 600; color: var(--cs-ink-2); background: var(--cs-surface); }
.chainsim-container .cs-kpi-value { font-size: 1.45rem; font-weight: 750; font-variant-numeric: tabular-nums; color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-kpi-delta { font-size: 0.82rem; font-weight: 600; min-height: 1.2em; color: var(--cs-ink-2); background: var(--cs-surface); }
.chainsim-container .cs-kpi-delta.cs-up { color: var(--cs-good); background: var(--cs-surface); }
.chainsim-container .cs-kpi-delta.cs-down { color: var(--cs-bad); background: var(--cs-surface); }
.chainsim-container .cs-kpi-ref { font-size: 0.75rem; color: var(--cs-ink-2); background: var(--cs-surface); }
.chainsim-container .cs-kpi.cs-alert { border-color: var(--cs-bad); box-shadow: inset 0 3px 0 var(--cs-bad); }
.chainsim-container .cs-kpi.cs-ok { box-shadow: inset 0 3px 0 var(--cs-good); }

.chainsim-container .cs-h2 { font-size: 1.15rem; line-height: 1.3; margin: 0 0 var(--cs-s3); font-weight: 700; color: var(--cs-ink); }
.chainsim-container .cs-h3 { font-size: 1rem; margin: var(--cs-s4) 0 var(--cs-s2); color: var(--cs-ink); }

.chainsim-container .cs-results { background: var(--cs-surface); border: 1px solid var(--cs-line); border-left: 6px solid var(--cs-focus); border-radius: var(--cs-r); padding: var(--cs-s4) var(--cs-s5); margin: var(--cs-s3) 0 var(--cs-s4); }
.chainsim-container .cs-results .cs-h2 { background: var(--cs-surface); }
.chainsim-container .cs-forecast-check { margin: 0 0 var(--cs-s3); padding: var(--cs-s2) var(--cs-s3); border-radius: 8px; color: var(--cs-ink); background: var(--cs-surface-2); }
.chainsim-container .cs-lines { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--cs-s2); }
.chainsim-container .cs-lines li { padding: var(--cs-s2) var(--cs-s3); border-radius: 8px; border-left: 4px solid var(--cs-line); color: var(--cs-ink); background: var(--cs-surface-2); }
.chainsim-container .cs-lines li.cs-tone-good { border-left-color: var(--cs-good); color: var(--cs-ink); background: var(--cs-good-soft); }
.chainsim-container .cs-lines li.cs-tone-warn { border-left-color: var(--cs-warn); color: var(--cs-ink); background: var(--cs-warn-soft); }
.chainsim-container .cs-lines li.cs-tone-bad { border-left-color: var(--cs-bad); color: var(--cs-ink); background: var(--cs-bad-soft); }
.chainsim-container .cs-tonetag { font-weight: 700; margin-right: var(--cs-s1); }
.chainsim-container .cs-hintline { margin: var(--cs-s3) 0 0; font-weight: 600; color: var(--cs-ink); background: var(--cs-surface); }

.chainsim-container .cs-main { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); gap: var(--cs-s4); align-items: start; }
.chainsim-container .cs-brief, .chainsim-container .cs-decide { background: var(--cs-surface); border: 1px solid var(--cs-line); border-radius: var(--cs-r); padding: var(--cs-s4) var(--cs-s5); }
.chainsim-container .cs-brief .cs-h2, .chainsim-container .cs-decide .cs-h2 { background: var(--cs-surface); }
.chainsim-container .cs-brief-text { color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-brief-text p { margin: 0 0 var(--cs-s2); }
.chainsim-container .cs-event { margin: var(--cs-s3) 0; padding: var(--cs-s3); border-radius: 8px; border: 1px solid var(--cs-warn); color: var(--cs-ink); background: var(--cs-warn-soft); }
.chainsim-container .cs-event strong { color: var(--cs-warn); background: var(--cs-warn-soft); }
.chainsim-container .cs-dataroom { margin: var(--cs-s3) 0; }
.chainsim-container .cs-dataroom h3 { font-size: 0.95rem; margin: var(--cs-s3) 0 var(--cs-s2); color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-dataroom ul { margin: 0; padding-left: 1.1em; }
.chainsim-container .cs-dataroom li { margin-bottom: var(--cs-s1); color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-dataroom .cs-unknown { color: var(--cs-ink-2); background: var(--cs-surface); font-style: italic; }
.chainsim-container .cs-principals { margin-top: var(--cs-s3); padding: var(--cs-s3); border-radius: 8px; color: var(--cs-ink); background: var(--cs-surface-2); }
.chainsim-container .cs-principals-head { margin: 0 0 var(--cs-s1); font-size: 0.8rem; font-weight: 700; color: var(--cs-ink-2); background: var(--cs-surface-2); }
.chainsim-container .cs-principals-text { margin: 0; font-style: italic; color: var(--cs-ink); background: var(--cs-surface-2); }

.chainsim-container .cs-panel { display: grid; gap: var(--cs-s3); }
.chainsim-container .cs-field { margin: 0; padding: 0; border: 0; min-width: 0; }
.chainsim-container fieldset.cs-field { border: 1px solid var(--cs-line); border-radius: 8px; padding: var(--cs-s3); }
.chainsim-container .cs-field legend, .chainsim-container .cs-field > label, .chainsim-container .cs-pair label { display: block; font-weight: 650; margin-bottom: var(--cs-s1); color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-field legend { padding: 0 var(--cs-s1); width: auto; max-width: 100%; float: none; font-size: 1rem; line-height: 1.4; }
.chainsim-container .cs-days { display: grid; grid-template-columns: minmax(0, 1fr) 6.5rem; gap: var(--cs-s2) var(--cs-s3); align-items: center; }
.chainsim-container .cs-days label { font-weight: 600; color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-days small { display: block; font-weight: 400; color: var(--cs-ink-2); background: var(--cs-surface); }
.chainsim-container .cs-pair { display: grid; grid-template-columns: 1fr 1fr; gap: var(--cs-s3); }
.chainsim-container select, .chainsim-container input[type=number], .chainsim-container input[type=text] {
    width: 100%; min-height: 44px; padding: var(--cs-s2) var(--cs-s3); font: inherit; color: var(--cs-ink); background: var(--cs-surface);
    border: 1px solid #8f877a; border-radius: 8px;
}
.chainsim-container select option { color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container select:hover, .chainsim-container input[type=number]:hover, .chainsim-container input[type=text]:hover { border-color: var(--cs-ink-2); }
.chainsim-container .cs-invalid { border-color: var(--cs-bad) !important; box-shadow: 0 0 0 2px var(--cs-bad-soft); }
.chainsim-container input[type=range] { width: 100%; min-height: 44px; accent-color: var(--cs-accent); }
.chainsim-container .cs-check { display: flex; align-items: flex-start; gap: var(--cs-s2); }
.chainsim-container .cs-check input { width: 22px; height: 22px; margin-top: 2px; accent-color: var(--cs-accent); flex: none; }
.chainsim-container .cs-check label { font-weight: 600; color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-readout { margin: 0; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-muted { font-weight: 400; color: var(--cs-ink-2); background: var(--cs-surface); }
.chainsim-container .cs-help { margin: var(--cs-s1) 0 0; font-size: 0.88rem; color: var(--cs-ink-2); background: var(--cs-surface); }
.chainsim-container .cs-live { margin: 0; font-size: 0.9rem; font-weight: 600; color: var(--cs-ink-2); background: var(--cs-surface); }
.chainsim-container .cs-live.cs-is-bad { color: var(--cs-bad); background: var(--cs-surface); }
.chainsim-container .cs-forecast { padding: var(--cs-s3); border-radius: 8px; border: 1px dashed var(--cs-focus); background: var(--cs-surface); }
.chainsim-container .cs-forecast label { color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-msg { margin: 0 0 var(--cs-s2); min-height: 0; color: var(--cs-bad); background: var(--cs-surface); font-weight: 600; }
.chainsim-container .cs-msg:empty { display: none; }

.chainsim-container .cs-actions { display: flex; flex-wrap: wrap; gap: var(--cs-s2); margin-top: var(--cs-s4); align-items: center; }
.chainsim-container .cs-btn-primary { min-height: 48px; padding: var(--cs-s2) var(--cs-s5); font-size: 1rem; font-weight: 700; color: var(--cs-accent-ink); background: var(--cs-accent); border: 2px solid var(--cs-accent); border-radius: 8px; cursor: pointer; }
.chainsim-container .cs-btn-primary:hover { color: var(--cs-accent-ink); background: #08573e; border-color: #08573e; }
.chainsim-container .cs-btn-primary:disabled { color: #ffffff; background: #56615c; border-color: #56615c; cursor: not-allowed; }
.chainsim-container .cs-btn-ghost { min-height: 44px; padding: var(--cs-s2) var(--cs-s4); font-weight: 600; color: var(--cs-ink); background: var(--cs-surface); border: 1px solid #8f877a; border-radius: 8px; cursor: pointer; }
.chainsim-container .cs-btn-ghost:hover { color: var(--cs-ink); background: var(--cs-surface-2); }

.chainsim-container .cs-end { background: var(--cs-surface); border: 1px solid var(--cs-line); border-left: 6px solid var(--cs-accent); border-radius: var(--cs-r); padding: var(--cs-s4) var(--cs-s5); margin-top: var(--cs-s4); }
.chainsim-container .cs-end .cs-h2 { background: var(--cs-surface); }

.chainsim-container .cs-details { margin-top: var(--cs-s4); background: var(--cs-surface); border: 1px solid var(--cs-line); border-radius: var(--cs-r); padding: var(--cs-s3) var(--cs-s5); }
.chainsim-container .cs-details summary { cursor: pointer; font-weight: 700; min-height: 44px; display: flex; align-items: center; color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-charts { display: grid; grid-template-columns: 1fr 1fr; gap: var(--cs-s4); margin: var(--cs-s3) 0; }
.chainsim-container .cs-chartbox { margin: 0; }
.chainsim-container .cs-chartbox figcaption { font-size: 0.9rem; font-weight: 600; margin-bottom: var(--cs-s2); color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-canvaswrap { position: relative; height: 240px; }
.chainsim-container .cs-tablewrap { overflow-x: auto; margin: var(--cs-s3) 0; }
.chainsim-container .cs-table { width: 100%; border-collapse: collapse; font-size: 0.88rem; font-variant-numeric: tabular-nums; }
.chainsim-container .cs-table caption { text-align: left; font-weight: 700; padding-bottom: var(--cs-s1); color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-table th, .chainsim-container .cs-table td { padding: 6px 8px; border-bottom: 1px solid var(--cs-line); text-align: right; color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-table th:first-child, .chainsim-container .cs-table td:first-child { text-align: left; }
.chainsim-container .cs-glossary { display: grid; grid-template-columns: max-content 1fr; gap: var(--cs-s2) var(--cs-s4); margin: var(--cs-s3) 0; }
.chainsim-container .cs-glossary dt { font-weight: 700; color: var(--cs-ink); background: var(--cs-surface); }
.chainsim-container .cs-glossary dd { margin: 0; color: var(--cs-ink-2); background: var(--cs-surface); }

/* debrief */
.chainsim-container .cs-db, .cs-db { font-family: system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; color: #1d1b18; background: #ffffff; line-height: 1.5; }
.cs-db .cs-db-head { display: flex; flex-wrap: wrap; gap: 12px 20px; align-items: baseline; margin-bottom: 12px; }
.cs-db .cs-db-score { font-size: 2.4rem; font-weight: 800; font-variant-numeric: tabular-nums; color: #0b6e4f; background: #ffffff; }
.cs-db .cs-db-score small { font-size: 1rem; font-weight: 600; color: #4a463f; background: #ffffff; }
.cs-db .cs-db-label { font-size: 1.2rem; font-weight: 700; color: #1d1b18; background: #ffffff; }
.cs-db .cs-db-sub { color: #4a463f; background: #ffffff; }
.cs-db .cs-db-badges { display: flex; flex-wrap: wrap; gap: 6px; margin: 4px 0 12px; }
.cs-db .cs-db-badge { padding: 2px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; color: #a1261b; background: #fbe6e3; }
.cs-db .cs-db-strip { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 8px; margin: 8px 0 16px; }
.cs-db .cs-db-m { border: 1px solid #d9d2c3; border-radius: 8px; padding: 6px 8px; color: #1d1b18; background: #ffffff; }
.cs-db .cs-db-m b { display: block; font-size: 1.1rem; font-variant-numeric: tabular-nums; color: #1d1b18; background: #ffffff; }
.cs-db .cs-db-m span { font-size: 0.78rem; color: #4a463f; background: #ffffff; }
.cs-db h4 { font-size: 1rem; margin: 14px 0 6px; color: #1d1b18; background: #ffffff; }
.cs-db .cs-db-turn { padding: 10px 12px; border-radius: 8px; border-left: 4px solid #a1261b; color: #1d1b18; background: #fbe6e3; }
.cs-db .cs-db-turn.cs-db-turn-good { border-left-color: #1f6b2e; color: #1d1b18; background: #e5f2e7; }
.cs-db ul, .cs-db ol { margin: 0; padding-left: 1.2em; }
.cs-db li { margin-bottom: 4px; color: #1d1b18; background: #ffffff; }
.cs-db table { border-collapse: collapse; width: 100%; font-size: 0.88rem; font-variant-numeric: tabular-nums; }
.cs-db th, .cs-db td { padding: 4px 6px; border-bottom: 1px solid #d9d2c3; text-align: right; color: #1d1b18; background: #ffffff; }
.cs-db th:first-child, .cs-db td:first-child, .cs-db th:nth-child(2), .cs-db td:nth-child(2) { text-align: left; }

/* focus, motion, small screens */
.chainsim-container :focus-visible, .cs-db :focus-visible { outline: 3px solid var(--cs-focus, #1a56db); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) {
    .chainsim-container *, .chainsim-container *::before, .chainsim-container *::after { transition: none !important; animation: none !important; scroll-behavior: auto !important; }
}
@media (max-width: 980px) {
    .chainsim-container .cs-kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .chainsim-container .cs-main { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 600px) {
    .chainsim-container { padding: var(--cs-s3); border-radius: 0; }
    .chainsim-container .cs-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .chainsim-container .cs-brief, .chainsim-container .cs-decide, .chainsim-container .cs-results, .chainsim-container .cs-details, .chainsim-container .cs-header { padding: var(--cs-s3); }
    .chainsim-container .cs-days, .chainsim-container .cs-pair, .chainsim-container .cs-charts { grid-template-columns: minmax(0, 1fr); }
    .chainsim-container .cs-title { font-size: 1.4rem; }
    .cs-db .cs-db-strip { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .chainsim-container .cs-glossary { grid-template-columns: minmax(0, 1fr); }
}

