            if (PRED && Number.isFinite(pv)) {
                var actual = ds[PRED[0]];
                ds.pred[round - 1] = { metric: PRED[0], p: pv, a: actual, err: r1(pv - actual), score: r2(clamp(1 - Math.abs(pv - actual) / PRED[1], 0, 1)) };
            }
            ds.log[round - 1] = lines;
            return lines;
        }

        function score(ds) {
            var otifS = clamp((ds.otif - 76) / (97 - 76), 0, 1);
            var costS = clamp((17.6 - ds.cost) / (17.6 - 12.8), 0, 1);
            var turnsS = clamp((ds.turns - 6.0) / (9.0 - 6.0), 0, 1);
            var cashS = clamp((ds.cash + 1.5) / 5, 0, 1);
            var ebitS = clamp((ds.ebit + 1.5) / 5.5, 0, 1);
            var outcome = 100 * (0.32 * otifS + 0.16 * costS + 0.18 * turnsS + 0.16 * cashS + 0.18 * ebitS);
            var n = 0, cal = 0;
            for (var i = 0; i < ds.pred.length; i++) { if (ds.pred[i]) { n++; cal += ds.pred[i].score; } }
            var rounds = Math.max(1, ds.roundsDone || 1);
            var calib = cal / rounds;
            var diag = clamp((ds.k.lane + ds.k.demand + ds.k.field) / 3 / 0.7, 0, 1);
            var process = 100 * (0.55 * calib + 0.45 * diag);
            var s = Math.round(0.8 * outcome + 0.2 * process);
            var cap = 100;
            if (ds.flags.clause) { cap = Math.min(cap, 68); }
            if (ds.flags.tender) { cap = Math.min(cap, 74); }
            if (ds.cash < -1.0) { cap = Math.min(cap, 55); }
            s = Math.min(s, cap);
            return { score: clamp(s, 0, 100), outcome: Math.round(outcome), process: Math.round(process), capped: s >= cap && cap < 100 ? cap : 0 };
        }

        return { init: init, step: step, score: score, z: z, PEER: PEER, COST_BASE: COST_BASE, OTIF_TRIP: OTIF_TRIP, OTIF_TARGET: OTIF_TARGET, TURNS_TARGET: TURNS_TARGET, CASH0: CASH0, REV0: REV0, GM: GM, RATE: RATE };
