    function lang() {
        var l = '';
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        if (!l) { l = (document.documentElement && document.documentElement.lang) || 'en'; }
        l = String(l).split('-')[0].toLowerCase();
        return TR[l] ? l : 'en';
    }
    function T(key, vars) {
        var s = null;
        try { if (window.mySimulation && typeof window.mySimulation.t === 'function') { s = window.mySimulation.t(key, vars); } } catch (e) {}
        if (s === null || s === undefined || s === key) {
            var d = TR[lang()] || TR.en;
            s = d[key] !== undefined ? d[key] : (TR.en[key] !== undefined ? TR.en[key] : key);
            if (vars) { s = String(s).replace(/\{(\w+)\}/g, function (m, k) { return vars[k] !== undefined ? vars[k] : m; }); }
        }
        return s;
    }
    function num(v, dec) {
        var n = Number(v);
        if (!Number.isFinite(n)) { return '–'; }
        var s = n.toFixed(dec === undefined ? 1 : dec);
        return lang() === 'es' ? s.replace('.', ',') : s;
    }
    function signed(v, dec) { var n = Number(v) || 0; return (n > 0 ? '+' : (n < 0 ? '−' : '±')) + num(Math.abs(n), dec); }
    function naira(v, dec) {
        var n = Number(v) || 0, neg = n < 0;
        var a = num(Math.abs(n), dec === undefined ? 2 : dec);
        if (lang() === 'es') { return (neg ? '−' : '') + a + ' mil M ₦'; }
        return (neg ? '−₦' : '₦') + a + 'bn';
    }
    function el(id) { return document.getElementById(id); }
    function esc(s) { return String(s === undefined || s === null ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split(String.fromCharCode(34)).join('&quot;'); }
