    class ChainAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Optimize the Chain';
            this.version = '2.0.0';
            this.ROUNDS = 4;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = ChainModel.init(Math.random);
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { daysLane: 0, daysDemand: 0, daysField: 0, fill: 61, cslHigh: 95, cslTail: 95, capex: 0, capture: false };
            }
            this._booted = true;
            try { this._render(state); } catch (e) {}
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var round = parseInt(state.currentPeriod, 10) || 1;
            var keys = DECISIONS[round] || [];
            var errors = [], self = this;
            this._clearInvalid();
            keys.forEach(function (k) {
                var c = el(k + 'Input');
                if (!c) { return; }
                var label = self._labelText(c);
                if (c.type === 'checkbox') { decisions[k] = !!c.checked; return; }
                if (k === 'note') { decisions[k] = String(c.value || '').replace(/[<>]/g, '').slice(0, 240); return; }
                if (CHOICES.indexOf(k) >= 0) {
                    decisions[k] = c.value;
                    if (!c.value) { errors.push([c, T('v_choose', { label: label })]); }
                    return;
                }
                var r = NUMS[k];
                var raw = String(c.value || '').replace(',', '.');
                var v = raw === '' ? NaN : Number(raw);
                if (raw === '' && /^predict/.test(k)) { errors.push([c, T('v_forecast')]); decisions[k] = ''; return; }
                if (!Number.isFinite(v) || v < r[0] || v > r[1]) { errors.push([c, T('v_range', { label: label, min: num(r[0], r[2] < 1 ? 1 : 0), max: num(r[1], r[2] < 1 ? 1 : 0) })]); return; }
                decisions[k] = v;
            });
            if (round === 1) {
                var tot = (Number(decisions.daysLane) || 0) + (Number(decisions.daysDemand) || 0) + (Number(decisions.daysField) || 0);
                if (tot > 20) { errors.push([el('daysLaneInput'), T('v_days', { n: tot })]); }
            }
            if (errors.length) {
                errors.forEach(function (e) { if (e[0]) { e[0].classList.add('cs-invalid'); e[0].setAttribute('aria-invalid', 'true'); } });
                var msg = el('formMsg');
                if (msg) { msg.textContent = errors[0][1] + (errors.length > 1 ? ' ' + T('v_fix') : ''); }
                try { if (errors[0][0] && errors[0][0].focus) { errors[0][0].focus(); } } catch (e) {}
                try { window.mySimulation.uiManager.showNotification(errors[0][1], 'warning'); } catch (e) {}
                return false;
            }
            return true;
        }

        calculateResults(state) {
            return this._computeRound(state);
        }

        _computeRound(state) {
            var ds = state.domainState;
            var round = parseInt(state.currentPeriod, 10) || 1;
            ChainModel.step(ds, state.decisions || {}, round);
            var sc = ChainModel.score(ds);
            ds.performance = { overallScore: sc.score, outcome: sc.outcome, process: sc.process };
            return {
                otif: ds.otif,
                logisticsCost: ds.cost,
                turns: ds.turns,
                cash: ds.cash,
                ebit: ds.ebit,
                period: round,
                trust: ds.trust,
                score: sc.score,
                summary: T('sum_r', { otif: num(ds.otif, 1), cost: num(ds.cost, 1) })
            };
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            // one source of truth: repaint whenever the framework repaints from state (after submit, undo, load)
            uiManager.bind('chainsimSync', 'currentPeriod', function (v) { try { self._render(window.mySimulation.state); } catch (e) {} return ''; });
            var watch = ['daysLaneInput', 'daysDemandInput', 'daysFieldInput', 'fillInput', 'cslHighInput', 'cslTailInput', 'segmentInput', 'capexInput'];
            watch.forEach(function (id) {
                var c = el(id);
                if (!c) { return; }
                c.addEventListener('input', function () { self._live(); });
                c.addEventListener('change', function () { self._live(); });
            });
            var root = el('chainsimRoot');
            if (root) {
                root.addEventListener('input', function (e) { var t = e.target; if (t && t.classList && t.classList.contains('cs-invalid')) { t.classList.remove('cs-invalid'); t.removeAttribute('aria-invalid'); } });
                root.addEventListener('change', function (e) { var t = e.target; if (t && t.classList && t.classList.contains('cs-invalid')) { t.classList.remove('cs-invalid'); t.removeAttribute('aria-invalid'); } });
            }
            var repaint = function () { try { self._render(window.mySimulation.state); } catch (e) {} };
            document.addEventListener('express:langchanged', function () { setTimeout(repaint, 0); });
            try {
                var bus = window.mySimulation && window.mySimulation.eventBus;
                if (bus && typeof bus.on === 'function') {
                    bus.on('language:changed', function () { setTimeout(repaint, 0); });
                    bus.on('period:undone', repaint);
                    bus.on('state:loaded', repaint);
                }
            } catch (e) {}
            this._ui = true;
        }

        _labelText(c) {
            var l = c.id ? document.querySelector('label[for="' + c.id + '"]') : null;
            if (!l) { return ''; }
            var sp = l.querySelector('span');
            return (sp ? sp.textContent : l.textContent).trim();
        }

        _clearInvalid() {
            var root = el('chainsimRoot');
            if (!root) { return; }
            var bad = root.querySelectorAll('.cs-invalid');
            for (var i = 0; i < bad.length; i++) { bad[i].classList.remove('cs-invalid'); bad[i].removeAttribute('aria-invalid'); }
            var msg = el('formMsg');
            if (msg) { msg.textContent = ''; }
        }

        _live() {
            var state = window.mySimulation && window.mySimulation.state;
            if (!state || !state.domainState) { return; }
            var ds = state.domainState;
            var a = Number((el('daysLaneInput') || {}).value) || 0, b = Number((el('daysDemandInput') || {}).value) || 0, c = Number((el('daysFieldInput') || {}).value) || 0;
            var used = a + b + c, dt = el('daysTotal');
            if (dt) {
                dt.textContent = used > 20 ? T('days_over', { used: used, over: used - 20 }) : T('days_total', { used: used, left: 20 - used });
                dt.classList.toggle('cs-is-bad', used > 20);
            }
            var fl = el('fillInput'), fr = el('fillReadout');
            if (fl && fr) { fr.textContent = fl.value; fl.setAttribute('aria-valuetext', fl.value + '%'); }
            var sp = el('stockPreview');
            if (sp) {
                var seg = (el('segmentInput') || {}).value || '';
                var h = Number(String((el('cslHighInput') || {}).value || '95').replace(',', '.'));
                var t = seg === 'one' ? h : Number(String((el('cslTailInput') || {}).value || '95').replace(',', '.'));
                if (Number.isFinite(h) && Number.isFinite(t)) {
                    var k = ds.k ? ds.k.demand : 0;
                    var sEff = seg === 'variability' ? 0.35 + 0.6 * k : (seg === 'value' ? 0.40 : (seg === 'volume' ? 0.35 : (seg === 'one' ? 0.15 : 0.40)));
                    h = Math.max(85, Math.min(99.5, h)); t = Math.max(80, Math.min(99, t));
                    var ss = 2.6 * (0.4 * ChainModel.z(h / 100) + 0.6 * ChainModel.z(t / 100)) / 1.645 * (1.6 - 0.8 * sEff);
                    sp.textContent = T('stock_preview', { ss: num(ss, 1), inv: num(6.6 + ss, 1), now: num(ds.inv, 1) });
                } else { sp.textContent = ''; }
            }
            var cp = el('capexPreview');
            if (cp) {
                var x = Number(String((el('capexInput') || {}).value || '0').replace(',', '.')) || 0;
                cp.textContent = T('capex_preview', { cash: naira(ds.cash - x, 2) });
                cp.classList.toggle('cs-is-bad', ds.cash - x < 0);
            }
        }

        _render(state) {
            if (!state || !state.domainState || !state.domainState.hist) { return; }
            if (!document.getElementById('chainsimRoot')) { return; }
            var ds = state.domainState, f = ds.flags || {};
            var done = (ds.roundsDone || 0) >= this.ROUNDS;
            var round = Math.min(this.ROUNDS, parseInt(state.currentPeriod, 10) || 1);
            var shown = done ? 0 : round;

            // round meta
            var rn = el('roundNameDisplay'); if (rn) { rn.textContent = done ? '' : '· ' + T('round_name_r' + round); }
            var ck = el('clockDisplay'); if (ck) { ck.textContent = done ? T('clock_end') : T('clock_r' + round); }
            var cl = el('clauseDisplay');
            if (cl) {
                var ck2 = f.clause ? 'clause_tripped' : (f.grace ? 'clause_grace' : ((ds.roundsDone || 0) >= 2 ? 'clause_cleared' : 'clause_open'));
                cl.textContent = T(ck2);
                cl.classList.toggle('cs-is-bad', !!f.clause);
                cl.classList.toggle('cs-is-good', ck2 === 'clause_cleared');
            }

            // KPIs
            var H = ds.hist, n = H.otif.length - 1, has = n >= 1;
            var put = function (id, text) { var e = el(id); if (e) { e.textContent = text; } };
            put('otifDisplay', num(ds.otif, 1) + '%');
            put('costDisplay', num(ds.cost, 1) + '%');
            put('turnsDisplay', num(ds.turns, 1) + 'x');
            put('cashDisplay', naira(ds.cash, 2));
            put('ebitDisplay', naira(ds.ebit, 2));
            put('turnsRef', T('turns_ref', { rev: num((ChainModel.REV0 - ds.lostRev) / ds.inv, 1) }));
            var delta = function (id, cur, prev, kind, goodUp) {
                var e = el(id); if (!e) { return; }
                e.classList.remove('cs-up', 'cs-down');
                if (!has) { e.textContent = T('delta_start'); return; }
                var d = cur - prev, dec = kind === 'bn' ? 2 : 1;
                if (Math.abs(d) < (kind === 'bn' ? 0.005 : 0.05)) { e.textContent = '± 0'; return; }
                var arrow = d > 0 ? '▲ ' : '▼ ';
                var key = kind === 'pts' ? 'delta_pts' : (kind === 'x' ? 'delta_x' : 'delta_bn');
                e.textContent = arrow + T(key, { s: d > 0 ? '+' : '−', d: num(Math.abs(d), dec) });
                e.classList.add((d > 0) === goodUp ? 'cs-up' : 'cs-down');
            };
            delta('otifDelta', H.otif[n], H.otif[n - 1], 'pts', true);
            delta('costDelta', H.cost[n], H.cost[n - 1], 'pts', false);
            delta('turnsDelta', H.turns[n], H.turns[n - 1], 'x', true);
            delta('cashDelta', H.cash[n], H.cash[n - 1], 'bn', true);
            delta('ebitDelta', H.ebit[n], H.ebit[n - 1], 'bn', true);
            var kO = el('kpiOtif'); if (kO) { kO.classList.toggle('cs-alert', ds.otif < ChainModel.OTIF_TRIP); kO.classList.toggle('cs-ok', ds.otif >= ChainModel.OTIF_TARGET); }
            var kC = el('kpiCash'); if (kC) { kC.classList.toggle('cs-alert', ds.cash < 0); }

            // panels and end state
            for (var i = 1; i <= this.ROUNDS; i++) { var p = el('round' + i + 'Panel'); if (p) { p.style.display = (i === shown) ? '' : 'none'; } }
            var play = el('playArea'); if (play) { play.style.display = done ? 'none' : ''; }
            var dec = document.querySelector('#chainsimRoot .cs-decide'); if (dec) { dec.style.display = done ? 'none' : ''; }
            var act = el('actionRow'); if (act) { act.style.display = done ? 'none' : ''; }
            var bt = el('briefingTitle'); if (bt) { bt.textContent = done ? T('briefing_title_end') : T('briefing_title_r' + round); }
            var btx = el('briefingText'); if (btx) { btx.innerHTML = done ? T('briefing_text_end') : T('briefing_text_r' + round); }

            // event
            var ev = el('eventCard'), evk = null, evv = {};
            if (!done && round === 2) { evk = 'ev_diesel'; evv = { pct: Math.round(ds.scenario.diesel * 100) }; }
            if (!done && round === 3) { evk = 'ev_r3'; evv = { days: ds.scenario.clearDays }; }
            if (!done && round === 4) { evk = 'ev_r4'; }
            if (ev) { if (evk) { ev.innerHTML = T(evk, evv); ev.style.display = ''; } else { ev.innerHTML = ''; ev.style.display = 'none'; } }

            // data room
            var dr = el('dataRoom');
            if (dr) { dr.innerHTML = done ? '' : this._dataRoom(ds, round); }

            // principals
            var co = el('coachText');
            if (co) {
                var ckey = 'coach_r1';
                if (done) { ckey = 'coach_r4_end'; }
                else if ((ds.roundsDone || 0) >= 1) { ckey = f.clause ? 'coach_tripped' : (f.grace && ds.otif < ChainModel.OTIF_TRIP ? 'coach_grace' : (ds.otif < ChainModel.OTIF_TRIP ? 'coach_risk' : 'coach_ok')); }
                co.textContent = T(ckey);
            }

            this._renderResults(state);
            this._renderTables(ds);
            this._renderGlossary();
            var end = el('endPanel'), eb = el('endDebrief');
            if (end && eb) {
                if (done) { eb.innerHTML = this.formatCompletionMessage(this.getPerformanceSummary(state.history || [])); end.style.display = ''; }
                else { eb.innerHTML = ''; end.style.display = 'none'; }
            }
            this._live();
            try { document.documentElement.setAttribute('lang', lang()); } catch (e) {}
        }

        _dataRoom(ds, round) {
            var f = ds.flags || {}, out = '', parts = ds.hist.parts[ds.hist.parts.length - 1];
            var costTable = '<h3>' + esc(T('dr_costs')) + '</h3><ul>';
            for (var i = 0; i < PARTS.length; i++) {
                var v = parts[PARTS[i]] || 0;
                if (PARTS[i] === 'port' && v <= 0) { continue; }
                costTable += '<li>' + esc(T('part_' + PARTS[i])) + ': ' + num(v, 1) + '%</li>';
            }
            costTable += '<li><strong>' + esc(T('part_total')) + ': ' + num(ds.cost, 1) + '%</strong></li></ul>';
            var lvl = function (k, hi, lo) { return k >= hi ? 'full' : (k >= lo ? 'part' : 'none'); };
            if (round === 1) {
                out += '<h3>' + esc(T('dr_title_today')) + '</h3>' + costTable + '<ul><li>' + esc(T('dr_fill', { fill: 61 })) + '</li><li>' + esc(T('dr_stock', { inv: num(ds.inv, 1), turns: num(ds.turns, 1), rturns: num(ChainModel.REV0 / ds.inv, 1) })) + '</li><li>' + esc(T('dr_cash', { cash: naira(ds.cash, 2) })) + '</li></ul>';
            } else if (round === 2) {
                var L = lvl(ds.k.lane, 0.6, 0.3), F = lvl(ds.k.field, 0.45, 0.2);
                out += '<h3>' + esc(T('dr_title_found')) + '</h3><ul>';
                out += '<li' + (L === 'none' ? ' class="cs-unknown"' : '') + '>' + esc(T('dr_lane_' + L)) + '</li>';
                if (f.firefight && L !== 'none') { out += '<li>' + esc(T('dr_masked')) + '</li>'; }
                out += '<li' + (F === 'none' ? ' class="cs-unknown"' : '') + '>' + esc(T('dr_field_' + F)) + '</li></ul>' + costTable;
            } else if (round === 3) {
                var D = lvl(ds.k.demand, 0.6, 0.3);
                out += '<h3>' + esc(T('dr_title_found')) + '</h3><ul><li' + (D === 'none' ? ' class="cs-unknown"' : '') + '>' + esc(T('dr_demand_' + D)) + '</li>';
                out += '<li>' + esc(T('dr_stock', { inv: num(ds.inv, 1), turns: num(ds.turns, 1), rturns: num((ChainModel.REV0 - ds.lostRev) / ds.inv, 1) })) + '</li><li>' + esc(T('dr_cash', { cash: naira(ds.cash, 2) })) + '</li></ul>';
            } else {
                out += '<h3>' + esc(T('dr_title_today')) + '</h3><ul><li>' + esc(T('dr_r4_otif', { otif: num(ds.otif, 1), trust: ds.trust })) + '</li><li>' + esc(T('dr_r4_cash', { cash: naira(ds.cash, 2) })) + '</li></ul>' + costTable;
            }
            return out;
        }

        _lineText(l) {
            var v = {}, src = l.vars || {};
            for (var k in src) { if (Object.prototype.hasOwnProperty.call(src, k)) { v[k] = (k === 'ss' || k === 'bn') ? num(src[k], k === 'bn' ? 2 : 1) : src[k]; } }
            return T(l.key, v);
        }

        _renderResults(state) {
            var ds = state.domainState, r = ds.roundsDone || 0, panel = el('resultsPanel');
            if (!panel) { return; }
            if (r < 1) { panel.style.display = 'none'; return; }
            panel.style.display = '';
            var tt = el('resultsTitle'); if (tt) { tt.textContent = T('results_title', { n: r, name: T('round_name_r' + r) }); }
            var fc = el('forecastCheck'), pr = ds.pred[r - 1];
            if (fc) {
                if (pr) {
                    var unit = pr.metric === 'turns' ? 'x' : '%', d = pr.metric === 'turns' ? 1 : 1;
                    fc.textContent = T('fc_line', { p: num(pr.p, d) + unit, a: num(pr.a, d) + unit, e: num(Math.abs(pr.err), d) + (pr.metric === 'turns' ? 'x' : ' pts') });
                } else { fc.textContent = T('fc_none'); }
            }
            var ul = el('resultsLines');
            if (ul) {
                var lines = ds.log[r - 1] || [], html = '';
                for (var i = 0; i < lines.length; i++) {
