                    html += '<li class="cs-tone-' + tone + '"><span class="cs-tonetag">' + esc(T('tone_' + tone)) + '</span>' + esc(this._lineText(lines[i])) + '</li>';
                }
                ul.innerHTML = html;
            }
            var hl = el('resultsHint');
            if (hl) { var h = this.getHint(state, {}); hl.textContent = h || ''; hl.style.display = h ? '' : 'none'; }
        }

        _renderTables(ds) {
            var H = ds.hist, n = H.otif.length, i, head = '<tr><th scope="col">' + esc(T('col_metric')) + '</th><th scope="col">' + esc(T('col_start')) + '</th>';
            for (i = 1; i < n; i++) { head += '<th scope="col">' + esc(T('col_r', { n: i })) + '</th>'; }
            head += '</tr>';
            var row = function (label, arr, fmt) { var s = '<tr><th scope="row">' + esc(label) + '</th>'; for (var j = 0; j < arr.length; j++) { s += '<td>' + fmt(arr[j]) + '</td>'; } return s + '</tr>'; };
            var kt = el('kpiTable');
            if (kt) {
                kt.innerHTML = '<caption>' + esc(T('tbl_kpi_caption')) + '</caption><thead>' + head + '</thead><tbody>'
                    + row(T('row_otif'), H.otif, function (v) { return num(v, 1); })
                    + row(T('row_cost'), H.cost, function (v) { return num(v, 1); })
                    + row(T('row_turns'), H.turns, function (v) { return num(v, 1); })
                    + row(T('row_cash'), H.cash, function (v) { return num(v, 2); })
                    + row(T('row_ebit'), H.ebit, function (v) { return num(v, 2); })
                    + row(T('row_trust'), H.trust, function (v) { return String(v); }) + '</tbody>';
            }
            var ct = el('costTable');
            if (ct) {
                var body = '';
                for (var p = 0; p < PARTS.length; p++) {
                    var key = PARTS[p], arr = H.parts.map(function (x) { return x[key] || 0; });
