                }
                body += row(T('part_total'), H.cost, function (v) { return num(v, 1); });
                ct.innerHTML = '<caption>' + esc(T('tbl_cost_caption')) + '</caption><thead>' + head + '</thead><tbody>' + body + '</tbody>';
            }
            var c1 = el('chainChart'); if (c1) { c1.setAttribute('aria-label', T('alt_otif', { series: H.otif.map(function (v) { return num(v, 1) + '%'; }).join(', ') })); }
            var c2 = el('costChart'); if (c2) { c2.setAttribute('aria-label', T('alt_cost', { series: H.cost.map(function (v) { return num(v, 1) + '%'; }).join(', ') })); }
        }

