        _band(score) {
            if (score >= 83) { return 'recovered'; }
            if (score >= 72) { return 'held'; }
            if (score >= 60) { return 'damaged'; }
            if (score >= 45) { return 'partial'; }
            return 'lost';
        }

        _story(ds, d) {
            var f = ds.flags || {}, mist = [], turn = null;
            var add = function (flag, tk, ik) { if (f[flag]) { if (!turn && tk) { turn = tk; } if (ik && mist.indexOf(ik) < 0) { mist.push(ik); } } };
            add('squeeze', 'turn_squeeze', 'ins_credit');
            if (f.credit && !f.squeeze) { mist.push('ins_credit'); }
            add('trapped', 'turn_trapped', 'ins_trapped');
            add('shockHit', 'turn_shock', 'ins_shock');
            add('firefight', 'turn_firefight', 'ins_firefight');
            add('byValue', 'turn_value', 'ins_value');
            add('byVolume', 'turn_qty', 'ins_qty');
            add('oneRule', 'turn_qty', 'ins_qty');
            add('blanket', 'turn_blanket', 'ins_blanket');
            add('promise', 'turn_promise', 'ins_promise');
            add('masterplan', 'turn_master', 'ins_master');
            add('central', 'turn_central', 'ins_central');
            add('railFail', 'turn_rail', null);
            add('cutOrders', 'turn_cut', 'ins_cut');
            add('underFleet', 'turn_fleet', null);
            add('overFill', 'turn_overfill', null);
            add('selfCollect', 'turn_selfcollect', null);
            add('deskOnly', 'turn_desk', 'ins_desk');
            add('termsLater', 'turn_terms', null);
            if (!turn && f.clause) { turn = 'turn_clause'; }
            if (ds.cash < 0) { mist.push('ins_overdraft'); }
            var goods = [];
            if (d.transfers === 'cap') { goods.push('ins_good_cap'); }
            if (d.window === 'predawn') { goods.push('ins_good_predawn'); }
            if (d.segment === 'variability' && ds.k.demand >= 0.5) { goods.push('ins_good_var'); }
            if (d.contract === 'pod' && d.model !== 'promise') { goods.push('ins_good_pod'); }
            if (d.credit === 'cod') { goods.push('ins_good_cod'); }
            var best = d.window === 'predawn' ? 'best_predawn' : (d.segment === 'variability' ? 'best_var' : (d.footprint === 'recut' ? 'best_recut' : 'best_pod'));
            var n = 0, cal = 0;
            for (var i = 0; i < ds.pred.length; i++) { if (ds.pred[i]) { n++; if (ds.pred[i].score >= 0.5) { cal++; } } }
            var fcKey = n && cal * 2 >= n ? 'ins_forecast_good' : 'ins_forecast_bad';
            var ins = mist.slice(0, 4);
            ins.push(fcKey);
            for (var g = 0; g < goods.length && ins.length < 5; g++) { ins.push(goods[g]); }
            return { turn: turn || 'turn_none', turnVars: { r: f.clauseRound || 2, best: T(best) }, insights: ins, good: !turn };
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation && window.mySimulation.state;
            var ds = state && state.domainState;
            if (!ds || !ds.hist) { return {}; }
            var d = state.decisions || {};
            var sc = ChainModel.score(ds), band = this._band(sc.score), st = this._story(ds, d);
            return {
                otif: ds.otif, cost: ds.cost, turns: ds.turns, cash: ds.cash, ebit: ds.ebit, trust: ds.trust,
                composite: sc.score, overallScore: sc.score, totalScore: sc.score, score: sc.score,
                outcome: sc.outcome, process: sc.process,
                performance: band, performanceKey: 'band_' + band, performanceLabel: T('band_' + band),
                met: band === 'recovered',
                clause: !!ds.flags.clause, tender: !!ds.flags.tender, overdraft: ds.cash < 0,
                turningPointKey: st.turn,
                insightKeys: st.insights,
                insights: st.insights.map(function (k) { return T(k); }),
                note: d.note || ''
            };
        }

        formatCompletionMessage(summary) {
            var state = window.mySimulation && window.mySimulation.state;
            var ds = state && state.domainState;
            var s = summary || {};
            if (!ds || !ds.hist) { return '<div class="cs-db"><p>' + esc(T('end_title')) + '</p></div>'; }
            var d = state.decisions || {}, st = this._story(ds, d);
            var score = typeof s.overallScore === 'number' ? s.overallScore : ChainModel.score(ds).score;
            var band = this._band(score), sc = ChainModel.score(ds);
            var badges = '';
            if (ds.flags.clause) { badges += '<span class="cs-db-badge">' + esc(T('badge_clause')) + '</span>'; }
            if (ds.flags.tender) { badges += '<span class="cs-db-badge">' + esc(T('badge_tender')) + '</span>'; }
            if (ds.cash < 0) { badges += '<span class="cs-db-badge">' + esc(T('badge_cash')) + '</span>'; }
            var m = function (v, label) { return '<div class="cs-db-m"><b>' + v + '</b><span>' + esc(T(label)) + '</span></div>'; };
            var strip = m(num(ds.otif, 1) + '%', 'm_otif') + m(num(ds.cost, 1) + '%', 'm_cost') + m(num(ds.turns, 1) + 'x', 'm_turns') + m(esc(naira(ds.cash, 2)), 'm_cash') + m(esc(naira(ds.ebit, 2)), 'm_ebit');
            var ins = st.insights.map(function (k) { return '<li>' + esc(T(k)) + '</li>'; }).join('');
            var fc = '';
            for (var i = 0; i < ds.pred.length; i++) {
                var p = ds.pred[i]; if (!p) { continue; }
                var u = p.metric === 'turns' ? 'x' : '%';
                fc += '<tr><td>' + (i + 1) + '</td><td>' + esc(T('fc_metric_' + p.metric)) + '</td><td>' + num(p.p, 1) + u + '</td><td>' + num(p.a, 1) + u + '</td></tr>';
            }
            var note = d.note ? '<h4>' + esc(T('db_note')) + '</h4><p>' + esc(d.note) + '</p>' : '';
            return '<div class="cs-db">'
                + '<div class="cs-db-head"><div class="cs-db-score">' + score + '<small>/100</small></div><div><div class="cs-db-label">' + esc(T('band_' + band)) + '</div><div class="cs-db-sub">' + esc(T('db_sub', { o: sc.outcome, p: sc.process })) + '</div></div></div>'
                + (badges ? '<div class="cs-db-badges">' + badges + '</div>' : '')
                + '<div class="cs-db-strip">' + strip + '</div>'
                + '<h4>' + esc(T('db_turning')) + '</h4><p class="cs-db-turn' + (st.good ? ' cs-db-turn-good' : '') + '">' + esc(T(st.turn, st.turnVars)) + '</p>'
                + '<h4>' + esc(T('db_insights')) + '</h4><ul>' + ins + '</ul>'
                + (fc ? '<h4>' + esc(T('db_forecasts')) + '</h4><table><thead><tr><th scope="col">' + esc(T('db_fc_round')) + '</th><th scope="col">' + esc(T('db_fc_metric')) + '</th><th scope="col">' + esc(T('db_fc_you')) + '</th><th scope="col">' + esc(T('db_fc_actual')) + '</th></tr></thead><tbody>' + fc + '</tbody></table>' : '')
                + note
                + '<h4>' + esc(T('db_questions')) + '</h4><ol><li>' + esc(T('q1')) + '</li><li>' + esc(T('q2')) + '</li><li>' + esc(T('q3')) + '</li></ol>'
                + '</div>';
        }

        getHint(state, results) {
            var ds = state && state.domainState;
            if (!ds || !ds.flags || !(ds.roundsDone >= 1)) { return null; }
            var f = ds.flags, r = ds.roundsDone, k = null;
            if (r === 1) { k = f.firefight ? 'hint_firefight' : (f.credit ? 'hint_credit' : (f.deskOnly ? 'hint_desk' : null)); }
            if (r === 2) { k = f.trapped ? 'hint_trapped' : (f.overFill ? 'hint_overfill' : (f.clause ? 'hint_clause' : null)); }
            if (r === 3) { k = f.blanket ? 'hint_blanket' : (f.byValue || f.byVolume || f.oneRule ? 'hint_value' : (f.central ? 'hint_central' : (f.cutOrders ? 'hint_cut' : null))); }
            if (r === 4) { k = f.promise ? 'hint_promise' : (f.masterplan ? 'hint_master' : (f.termsLater ? 'hint_terms' : null)); }
            return k ? T('hint_prefix') + T(k) : null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.otif', label: 'OTIF', i18nKey: 'col_otif', formatter: function (v) { return num(v, 1) + '%'; } },
                { key: 'results.logisticsCost', label: 'Cost %', i18nKey: 'col_cost', formatter: function (v) { return num(v, 1) + '%'; } },
                { key: 'results.turns', label: 'Turns', i18nKey: 'col_turns', formatter: function (v) { return num(v, 1) + 'x'; } },
                { key: 'results.cash', label: 'Cash', i18nKey: 'col_cash', formatter: function (v) { return naira(v, 2); } }
            ];
        }

        getPresets() { return null; }

        getTranslations() { return TR; }
    }

    document.addEventListener('DOMContentLoaded', function () {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new ChainAdapter(), {
            simulationType: 'optimize_the_chain',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
